<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {gsap} from 'gsap'
import {useWorkbench} from '../stores/workbench'
import {progress,validApproval,projectActive} from '../lib/domain'
import Icon from '../components/Icon.vue'
import ProjectCard from '../components/ProjectCard.vue'
const emit=defineEmits<{create:[]}>(),store=useWorkbench(),root=ref<HTMLElement>(),idea=ref('');let context:gsap.Context|undefined
const completed=computed(()=>store.state.projects.reduce((sum,p)=>sum+progress(p),0));const pending=computed(()=>store.state.projects.filter(projectActive).flatMap(p=>store.catalog.gates.filter(g=>g.after.every(id=>p.nodes[id].status==='COMPLETED')&&!validApproval(p,g)).map(g=>({project:p,gate:g}))).slice(0,3))
const quickStages=[{name:'灵感与选题',note:'找到值得表达的事',icon:'Lightbulb',stage:'IDEATION',range:'08—15'},{name:'脚本与分镜',note:'把想法讲清楚',icon:'FileText',stage:'PREPRODUCTION',range:'16—24'},{name:'素材与制作',note:'让画面发生',icon:'Clapperboard',stage:'PRODUCTION',range:'25—30'},{name:'剪辑与包装',note:'认真打磨每一帧',icon:'Scissors',stage:'POSTPRODUCTION',range:'31—41'},{name:'发布与复盘',note:'让作品遇见观众',icon:'Send',stage:'DELIVERY',range:'42—50'}]
async function capture(){if(await store.command({type:'ADD_IDEA',payload:{text:idea.value}},'想法已收好，去灵感收件箱继续整理'))idea.value=''}
onMounted(()=>{if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)context=gsap.context(()=>{gsap.fromTo('.journey-line-fill',{scaleX:0},{scaleX:1,duration:1.3,ease:'expo.out',delay:.15});gsap.fromTo('.journey-stop',{y:8,opacity:.65},{y:0,opacity:1,duration:.6,stagger:.07,ease:'power3.out'});gsap.to('.orbit-dot',{rotation:360,transformOrigin:'-22px 0px',duration:18,repeat:-1,ease:'none'})},root.value)});onUnmounted(()=>context?.revert())
</script>
<template><div ref="root" class="page-content dashboard"><div class="page-heading dashboard-heading"><div><div class="date-line"><span class="tiny-spark">✳</span>今天也是适合创作的一天<span class="date-separator"/>{{new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Shanghai'}).format(new Date())}}</div><h1>让好想法，成为下一条作品<span class="heading-dot">.</span></h1><p>从脑海里的灵光一闪，到被看见的那一刻。每一步，都在这里。</p></div><button class="btn primary" @click="emit('create')"><Icon name="Plus" :size="17"/>新建作品</button></div><section class="journey" aria-label="完整制作流程"><div class="section-top"><span class="section-kicker"><span class="mini-orbit"><i class="orbit-dot"/></span>你的创作旅程</span><RouterLink to="/workflow" class="text-link">查看全部 {{store.catalog.nodes.length}} 个节点<Icon name="ArrowUpRight" :size="15"/></RouterLink></div><div class="journey-stops"><div class="journey-line"><div class="journey-line-fill"/></div><RouterLink v-for="(stage,i) in quickStages" :key="stage.name" :to="{path:'/workflow',query:{stage:stage.stage}}" :class="['journey-stop',{current:i===1}]"><div class="journey-icon"><Icon :name="stage.icon" :size="21"/></div><span class="journey-index">0{{i+1}}</span><strong>{{stage.name}}</strong><small>{{stage.note}}</small></RouterLink></div><div class="journey-caption"><span><Icon name="Bot" :size="14"/>流程管理已就绪，节点支持 Agent 协作</span><span>6 个阶段拍板<Icon name="CheckCheck" :size="14"/></span></div></section><section class="projects-section"><div class="section-heading"><div><h2>正在创作<span class="count-label">{{store.state.projects.length}}</span></h2><p>每一份表达，都值得认真完成。</p></div><RouterLink to="/projects" class="text-link">全部作品<Icon name="ArrowRight" :size="16"/></RouterLink></div><div class="project-grid"><ProjectCard v-for="project in store.state.projects.slice(0,3)" :key="project.id" :project="project"/><button class="new-project-tile" v-if="!store.state.projects.length" @click="emit('create')"><span><Icon name="Plus" :size="24"/></span><strong>你的第一条作品</strong><small>不需要完美的计划，从一个想法开始。</small></button></div><p class="sample-note" v-if="store.state.projects.some(p=>p.sample)"><Icon name="Info" :size="13"/>带“示例”标记的作品仅用于体验流程。新建作品将独立保存。</p></section><div class="dashboard-lower"><section class="capture-box"><div class="section-heading compact"><h2><Icon name="Lightbulb" :size="18"/>灵感，先收好</h2><RouterLink to="/ideas" class="text-link">收件箱<Icon name="ArrowUpRight" :size="14"/></RouterLink></div><p>一个问题、一段经历，或者一个还没想清楚的念头。</p><form class="capture-input" @submit.prevent="capture"><input v-model="idea" aria-label="记录灵感" placeholder="此刻，你想表达什么？" maxlength="2000"><button type="submit" class="icon-btn capture-submit" aria-label="保存灵感" :disabled="!idea.trim()"><Icon name="ArrowUp" :size="18"/></button></form><span class="capture-hint">不用整理好，先让它留下来。</span></section><section class="attention-box"><div class="section-heading compact"><h2>留一点时间，做决定<span class="attention-dot"/></h2><RouterLink to="/approvals" class="text-link">查看全部<Icon name="ArrowUpRight" :size="14"/></RouterLink></div><div v-for="item in pending.slice(0,2)" :key="item.project.id+item.gate.id" class="attention-row"><span class="attention-icon"><Icon name="CheckCheck" :size="17"/></span><div><b>{{item.gate.name}}</b><small>{{item.project.title}}<span v-if="item.project.sample"> · 示例</span></small></div><RouterLink :to="'/projects/'+item.project.id+'?gate='+item.gate.id" class="icon-btn" :aria-label="'审阅'+item.gate.name"><Icon name="ArrowUpRight" :size="17"/></RouterLink></div><p class="muted empty-copy" v-if="!pending.length">暂时没有待拍板事项，安心创作。</p></section></div><div class="dashboard-footnote"><span><Icon name="FolderHeart" :size="15"/>{{completed}} 个已完成节点<span class="muted">（含示例）</span></span><RouterLink to="/models">配置你的模型团队<Icon name="ArrowRight" :size="14"/></RouterLink></div></div></template>
